-- Rebuild Medina Book 4 lesson 8 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 31-35. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '8';
  if existing_count <> 6 then
    raise exception 'Expected 6 Book 4 lesson 8 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'بَابُ اِسْتَفْعَلَ (порода اِسْتَفْعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِسْتَفْعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالسِّينِ وَالتَّاءِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِسْتِفْعَالٍ. وَمِنْ مَعَانِيهِ الطَّلَبُ، وَالصَّيْرُورَةُ، وَالتَّشَبُّهُ.</span><p class="rule-study-text">Порода اِسْتَفْعَلَ содержит соединительную хамзу, س и ت; масдар строится по модели اِسْتِفْعَالٌ. Шарх объясняет три значения: просьбу или поиск, превращение и уподобление.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">أَحْرُفُ الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالسِّينُ وَالتَّاءُ</span><span class="rule-term-ru">добавочные элементы — соединительная хамза, س и ت</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِسْتِفْعَالٌ</span><span class="rule-term-ru">масдар по модели اِسْتِفْعَالٌ</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الطَّلَبُ</span><span class="rule-term-ru">просьба или поиск</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الصَّيْرُورَةُ</span><span class="rule-term-ru">превращение в новое состояние</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">التَّشَبُّهُ</span><span class="rule-term-ru">уподобление</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Исходные примеры породы</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَخْرَجَ</span><span class="rule-example-ru">извлёк</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَكْبَرَ</span><span class="rule-example-ru">возгордился</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَعَانَ</span><span class="rule-example-ru">попросил помощи</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَغْنَى</span><span class="rule-example-ru">стал независимым, не нуждающимся</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Образование масдара</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَكْبَرَ ← اِسْتِكْبَارٌ</span><span class="rule-example-ru">возгордился → высокомерие</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَغْنَى ← اِسْتِغْنَاءٌ</span><span class="rule-example-ru">стал независимым → независимость, отсутствие нужды</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَغْفَرَ ← اِسْتِغْفَارٌ</span><span class="rule-example-ru">попросил прощения → просьба о прощении</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три значения породы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّفْسِيرُ</span><span class="rule-table-ru">пояснение и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّلَبُ</span><span class="rule-table-ru">просьба или поиск</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَغْفَرَ، وَاِسْتَهْدَى</span><span class="rule-table-ru">попросил прощения; попросил наставления</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">طَلَبَ الْمَغْفِرَةَ وَالْهِدَايَةَ</span><span class="rule-table-ru">попросил прощения и руководства</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصَّيْرُورَةُ</span><span class="rule-table-ru">превращение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَحْجَرَ الطِّينُ.</span><span class="rule-table-ru">Глина окаменела.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">صَارَ حَجَرًا</span><span class="rule-table-ru">стала камнем</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّشَبُّهُ</span><span class="rule-table-ru">уподобление</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَرْجَلَتِ الْمَرْأَةُ.</span><span class="rule-table-ru">Женщина стала уподобляться мужчине.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَشَبَّهَتْ بِالرَّجُلِ</span><span class="rule-table-ru">уподобилась мужчине</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَخْرَجَ</span><span class="rule-table-ru">извлёк</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَسْتَخْرِجُ</span><span class="rule-table-ru">извлекает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَخْرِجْ</span><span class="rule-table-ru">извлеки</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْتِخْرَاجٌ</span><span class="rule-table-ru">извлечение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسْتَخْرِجٌ</span><span class="rule-table-ru">извлекающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُسْتَخْرَجٌ</span><span class="rule-table-ru">извлечённый</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَهْدَى</span><span class="rule-table-ru">попросил наставления</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَسْتَهْدِي</span><span class="rule-table-ru">просит наставления</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَهْدِ</span><span class="rule-table-ru">проси наставления</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْتِهْدَاءٌ</span><span class="rule-table-ru">просьба о наставлении</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسْتَهْدٍ</span><span class="rule-table-ru">ищущий наставления</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُسْتَهْدًى</span><span class="rule-table-ru">тот, у кого просят наставления</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَعَاذَ</span><span class="rule-table-ru">попросил защиты</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَسْتَعِيذُ</span><span class="rule-table-ru">просит защиты</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَعِذْ</span><span class="rule-table-ru">проси защиты</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْتِعَاذَةٌ</span><span class="rule-table-ru">просьба о защите</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسْتَعِيذٌ</span><span class="rule-table-ru">просящий защиты</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">глагол непереходный; форма не приводится</span></td></tr></tbody></table></div></div></div>', 'Порода اِسْتَفْعَلَ содержит соединительную хамзу, س и ت; масдар строится по модели اِسْتِفْعَالٌ. Шарх объясняет три значения: просьбу или поиск, превращение и уподобление.', 'بَابُ اِسْتَفْعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالسِّينِ وَالتَّاءِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِسْتِفْعَالٍ. وَمِنْ مَعَانِيهِ الطَّلَبُ، وَالصَّيْرُورَةُ، وَالتَّشَبُّهُ.'),
    (2, 'نَفْيُ الْمَاضِي بِلَا النَّافِيَةِ (отрицание прошедшего действия частицей لَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا نُفِيَ الْفِعْلُ الْمَاضِي بِلَا النَّافِيَةِ وَجَبَ تَكْرَارُهَا.</span><p class="rule-study-text">При отрицании прошедшего действия частицей لَا шарх требует повторить لَا перед вторым однородным глаголом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿فَلَا صَدَّقَ وَلَا صَلَّىٰ﴾</span><span class="rule-example-ru">«Он не уверовал и не совершил молитву»: отрицательная لَا повторена.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَا أَكَلْتُ وَلَا شَرِبْتُ.</span><span class="rule-example-ru">Я не ел и не пил.</span></div></div></div></div>', 'При отрицании прошедшего действия частицей لَا шарх требует повторить لَا перед вторым однородным глаголом.', 'إِذَا نُفِيَ الْفِعْلُ الْمَاضِي بِلَا النَّافِيَةِ وَجَبَ تَكْرَارُهَا.'),
    (3, 'دُخُولُ قَدْ عَلَى الْجُمْلَةِ الْحَالِيَّةِ (قَدْ в глагольном предложении состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا دَخَلَتْ وَاوُ الْحَالِ عَلَى جُمْلَةٍ فِعْلِيَّةٍ فِعْلُهَا مَاضٍ مُثْبَتٌ دَخَلَتْ مَعَهَا قَدْ، وَتَكُونُ الْجُمْلَةُ حَالًا فِي مَحَلِّ نَصْبٍ.</span><p class="rule-study-text">Если وَاوُ الْحَالِ вводит утвердительное глагольное предложение с глаголом прошедшего времени, вместе с ней употребляется قَدْ. Всё предложение занимает винительное место обстоятельства состояния.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">وَاوُ الْحَالِ</span><span class="rule-term-ru">وَاو, вводящая предложение состояния</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ مُثْبَتٌ</span><span class="rule-term-ru">утвердительный глагол прошедшего времени</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">حَالٌ فِي مَحَلِّ نَصْبٍ</span><span class="rule-term-ru">в винительном месте обстоятельства состояния</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">دَخَلْتُ الْمَسْجِدَ وَقَدْ رَكَعَ الْإِمَامُ.</span><span class="rule-example-ru">Я вошёл в мечеть, когда имам уже совершил поясной поклон.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">جُمْلَةُ «قَدْ رَكَعَ الْإِمَامُ» حَالٌ فِي مَحَلِّ نَصْبٍ.</span><span class="rule-example-ru">Предложение «имам уже совершил поясной поклон» является обстоятельством состояния в винительном месте.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">دَخَلْتُ الْفَصْلَ وَقَدْ شَرَحَ الْمُدَرِّسُ الدَّرْسَ.</span><span class="rule-example-ru">Я вошёл в аудиторию, когда преподаватель уже объяснил урок.</span></div></div></div></div>', 'Если وَاوُ الْحَالِ вводит утвердительное глагольное предложение с глаголом прошедшего времени, вместе с ней употребляется قَدْ. Всё предложение занимает винительное место обстоятельства состояния.', 'إِذَا دَخَلَتْ وَاوُ الْحَالِ عَلَى جُمْلَةٍ فِعْلِيَّةٍ فِعْلُهَا مَاضٍ مُثْبَتٌ دَخَلَتْ مَعَهَا قَدْ، وَتَكُونُ الْجُمْلَةُ حَالًا فِي مَحَلِّ نَصْبٍ.'),
    (4, 'نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ (частицы винительного наклонения глагола настояще-будущего времени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-nasb" dir="rtl" lang="ar">نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ أَرْبَعَةٌ: أَنْ، وَلَنْ، وَكَيْ، وَإِذَنْ. أَنْ لِلنَّصْبِ وَالْمَصْدَرِ وَالِاسْتِقْبَالِ، وَلَنْ لِلنَّصْبِ وَالنَّفْيِ وَالِاسْتِقْبَالِ، وَكَيْ لِلنَّصْبِ وَالْمَصْدَرِ وَالِاسْتِقْبَالِ، وَإِذَنْ لِلنَّصْبِ وَالْجَوَابِ وَالْجَزَاءِ وَالِاسْتِقْبَالِ بِشُرُوطٍ ثَلَاثَةٍ.</span><p class="rule-study-text">Шарх разбирает четыре частицы, ставящие الْفِعْلُ الْمُضَارِعُ в винительное наклонение: أَنْ, لَنْ, كَيْ и إِذَنْ. Для каждой сохранены значение, примеры и разбор; для إِذَنْ — также три условия действия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре частицы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْحَرْفُ</span><span class="rule-table-ru">частица</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَانِيهِ</span><span class="rule-table-ru">значения</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِثَالٌ</span><span class="rule-table-ru">краткий пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ</span><span class="rule-table-ru">частица أَنْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصْبُ وَالْمَصْدَرُ وَالِاسْتِقْبَالُ</span><span class="rule-table-ru">винительное наклонение, образование масдара и будущее значение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُرِيدُ أَنْ أَشْرَبَ.</span><span class="rule-table-ru">Я хочу выпить.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَنْ</span><span class="rule-table-ru">частица لَنْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصْبُ وَالنَّفْيُ وَالِاسْتِقْبَالُ</span><span class="rule-table-ru">винительное наклонение, отрицание и будущее значение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَنْ تَذْهَبَ مَعِيَ.</span><span class="rule-table-ru">Ты не пойдёшь со мной.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَيْ</span><span class="rule-table-ru">частица كَيْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصْبُ وَالْمَصْدَرُ وَالِاسْتِقْبَالُ</span><span class="rule-table-ru">винительное наклонение, образование масдара и будущее значение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جِئْتُ كَيْ أَتَعَلَّمَ.</span><span class="rule-table-ru">Я пришёл, чтобы учиться.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِذَنْ</span><span class="rule-table-ru">частица إِذَنْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصْبُ وَالْجَوَابُ وَالْجَزَاءُ وَالِاسْتِقْبَالُ</span><span class="rule-table-ru">винительное наклонение, ответ, следствие и будущее значение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَنْ أَنْتَظِرَكَ.</span><span class="rule-table-ru">Тогда я буду ждать тебя.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">أَنْ — примеры и масдар</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">أُرِيدُ أَنْ أَشْرَبَ. التَّقْدِيرُ: أُرِيدُ الشُّرْبَ.</span><span class="rule-example-ru">Я хочу выпить. Замена масдаром: «Я хочу питья».</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ﴾</span><span class="rule-example-ru">«Аллах желает принять ваше покаяние»: التَّقْدِيرُ — يُرِيدُ اللَّهُ التَّوْبَةَ عَلَيْكُمْ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">لَنْ — отрицание будущего</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَنْ تَذْهَبَ مَعِيَ.</span><span class="rule-example-ru">Ты не пойдёшь со мной.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا﴾</span><span class="rule-example-ru">«Он сказал: “Ты не сможешь сохранять терпение вместе со мной”».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Кَيْ и لَامُ التَّعْلِيلِ</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">تَقْتَرِنُ كَيْ بِلَامِ التَّعْلِيلِ كَثِيرًا</span><span class="rule-term-ru">كَيْ часто соединяется с لَام цели</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">إِنْ لَمْ تَقْتَرِنْ بِهَا فَهِيَ مُقَدَّرَةٌ</span><span class="rule-term-ru">если لَام не выражена, она подразумевается</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">تَتَّصِلُ بِهَا لَا النَّافِيَةُ: لِكَيْلَا</span><span class="rule-term-ru">к ней может присоединиться отрицательная لَا; пишется لِكَيْلَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">كَيْ — все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">جِئْتُ لِكَيْ أَتَعَلَّمَ. التَّقْدِيرُ: جِئْتُ لِلتَّعَلُّمِ.</span><span class="rule-example-ru">Я пришёл, чтобы учиться. Замена: «Я пришёл для учёбы».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">جِئْتُ كَيْ أَتَعَلَّمَ.</span><span class="rule-example-ru">Я пришёл, чтобы учиться.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">اِجْتَهَدْتُ لِكَيْلَا أَرْسُبَ.</span><span class="rule-example-ru">Я старался, чтобы не провалиться.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡ﴾</span><span class="rule-example-ru">«Чтобы это не доставалось одним лишь богатым среди вас».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: جِئْتُ لِكَيْ أَتَعَلَّمَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">جِئْتُ: فِعْلٌ مَاضٍ مِنْ جَاءَ، مَبْنِيٌّ عَلَى السُّكُونِ لِاتِّصَالِهِ بِالتَّاءِ، وَالتَّاءُ ضَمِيرُ رَفْعٍ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.</span><span class="rule-example-ru">جِئْتُ — прошедший глагол от جَاءَ на сукуне из-за присоединения ت; ت — местоимение на дамме в именительном месте исполнителя.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">اللَّامُ: حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">لَـ — неизменяемый на касре предлог без синтаксического места.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">كَيْ: حَرْفُ نَصْبٍ وَمَصْدَرٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">كَيْ — неизменяемая на сукуне частица винительного наклонения и масдара без синтаксического места.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">أَتَعَلَّمَ: فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِكَيْ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَالْمَصْدَرُ الْمُؤَوَّلُ «كَيْ أَتَعَلَّمَ» فِي مَحَلِّ جَرٍّ.</span><span class="rule-example-ru">أَتَعَلَّمَ — глагол в винительном наклонении после كَيْ с явной фатхой; конструкция كَيْ أَتَعَلَّمَ занимает родительное место.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три условия действия إِذَنْ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَيَانُهُ</span><span class="rule-table-ru">точное содержание</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ تَتَصَدَّرَ جُمْلَةَ الْجَوَابِ</span><span class="rule-table-ru">первое условие</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَكُونُ إِذَنْ فِي صَدْرِ جُمْلَةِ الْجَوَابِ</span><span class="rule-table-ru">إِذَنْ должна начинать ответное предложение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَلَّا يَفْصِلَ بَيْنَهَا وَبَيْنَ الْفِعْلِ فَاصِلٌ إِلَّا الْقَسَمَ أَوْ لَا النَّافِيَةَ</span><span class="rule-table-ru">второе условие</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُسْمَحُ بِالْقَسَمِ أَوْ لَا النَّافِيَةِ فَقَطْ</span><span class="rule-table-ru">между ними допустимы только клятва либо отрицательная لَا</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ يَكُونَ زَمَنُ الْفِعْلِ الِاسْتِقْبَالَ</span><span class="rule-table-ru">третье условие</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَدُلُّ الْفِعْلُ عَلَى الْمُسْتَقْبَلِ</span><span class="rule-table-ru">глагол должен обозначать будущее</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">إِذَنْ действует: условия выполнены</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">سَأَزُورُكَ غَدًا. إِذَنْ أَنْتَظِرَكَ.</span><span class="rule-example-ru">«Я навещу тебя завтра». — «Тогда я буду ждать тебя».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِذَنْ وَاللَّهِ أَنْتَظِرَكَ.</span><span class="rule-example-ru">Тогда, клянусь Аллахом, я буду ждать тебя: между частицей и глаголом стоит клятва.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِذَنْ لَا أَخْرُجَ مِنَ الْبَيْتِ.</span><span class="rule-example-ru">Тогда я не выйду из дома: между частицей и глаголом стоит отрицательная لَا.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">إِذَنْ не действует: условие нарушено</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">سَبَبُ الرَّفْعِ</span><span class="rule-table-ru">почему глагол остаётся в именительном наклонении</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنَا إِذَنْ أَنْتَظِرُكَ.</span><span class="rule-table-ru">Я тогда жду тебя.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">إِذَنْ غَيْرُ مُتَصَدِّرَةٍ</span><span class="rule-table-ru">إِذَنْ не стоит в начале ответа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَنْ أَنَا أَنْتَظِرُكَ.</span><span class="rule-table-ru">Тогда я жду тебя.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْفَاصِلُ لَيْسَ الْقَسَمَ وَلَا لَا النَّافِيَةَ</span><span class="rule-table-ru">разделитель — не клятва и не отрицательная لَا</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَنْ أَنْتَظِرُكَ الْآنَ.</span><span class="rule-table-ru">Тогда я жду тебя сейчас.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">زَمَنُ الْفِعْلِ الْحَالُ</span><span class="rule-table-ru">глагол обозначает настоящее, а не будущее</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: إِذَنْ أَنْتَظِرَكَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِذَنْ: حَرْفُ نَصْبٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">إِذَنْ — неизменяемая на сукуне частица винительного наклонения без синтаксического места.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَنْتَظِرَكَ: فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِإِذَنْ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنَا.</span><span class="rule-example-ru">أَنْتَظِرَكَ — глагол в винительном наклонении после إِذَنْ с явной фатхой; исполнитель — скрытое «я».</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">وَكَافُ الْمُخَاطَبِ: ضَمِيرُ نَصْبٍ مُتَّصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.</span><span class="rule-example-ru">كَافُ الْمُخَاطَبِ — присоединённое местоимение винительного разряда на фатхе в месте прямого дополнения.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: إِذَنْ وَاللَّهِ أَنْتَظِرَكَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِذَنْ: حَرْفُ نَصْبٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">إِذَنْ — неизменяемая на сукуне частица винительного наклонения без синтаксического места.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">وَاللَّهِ: الْوَاوُ لِلْقَسَمِ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَلَفْظُ الْجَلَالَةِ «اللَّهِ» اسْمٌ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">В وَاللَّهِ буква وَاو — предлог клятвы на фатхе без синтаксического места; имя Аллаха стоит в родительном падеже с явной касрой.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">وَجُمْلَةُ الْقَسَمِ لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ؛ لِأَنَّهَا جُمْلَةٌ اعْتِرَاضِيَّةٌ.</span><span class="rule-example-ru">Предложение клятвы не имеет синтаксического места, поскольку является вставным.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَنْتَظِرَكَ: يُعْرَبُ الْإِعْرَابَ السَّابِقَ.</span><span class="rule-example-ru">أَنْتَظِرَكَ разбирается так же, как в предыдущем примере.</span></div></div></div></div>', 'Шарх разбирает четыре частицы, ставящие الْفِعْلُ الْمُضَارِعُ в винительное наклонение: أَنْ, لَنْ, كَيْ и إِذَنْ. Для каждой сохранены значение, примеры и разбор; для إِذَنْ — также три условия действия.', 'نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ أَرْبَعَةٌ: أَنْ، وَلَنْ، وَكَيْ، وَإِذَنْ. أَنْ لِلنَّصْبِ وَالْمَصْدَرِ وَالِاسْتِقْبَالِ، وَلَنْ لِلنَّصْبِ وَالنَّفْيِ وَالِاسْتِقْبَالِ، وَكَيْ لِلنَّصْبِ وَالْمَصْدَرِ وَالِاسْتِقْبَالِ، وَإِذَنْ لِلنَّصْبِ وَالْجَوَابِ وَالْجَزَاءِ وَالِاسْتِقْبَالِ بِشُرُوطٍ ثَلَاثَةٍ.'),
    (5, 'مَعَانِي جَعَلَ (четыре значения глагола جَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">لِجَعَلَ أَرْبَعَةُ مَعَانٍ: مَعْنَى صَيَّرَ وَمَعْنَى ظَنَّ، وَفِي هَذَيْنِ تَنْصِبُ مَفْعُولَيْنِ؛ وَتَأْتِي مِنْ أَفْعَالِ الشُّرُوعِ فَتَعْمَلُ عَمَلَ كَانَ؛ وَتَأْتِي بِمَعْنَى أَوْجَدَ فَتَكُونُ فِعْلًا تَامًّا يَنْصِبُ مَفْعُولًا وَاحِدًا.</span><p class="rule-study-text">جَعَلَ может означать «превратить», «счесть», начало действия либо «создать». Первые два значения требуют два дополнения, значение начала действует как كَانَ, а значение создания требует одно дополнение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре значения и управление</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْعَمَلُ</span><span class="rule-table-ru">управление</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَى صَيَّرَ</span><span class="rule-table-ru">значение «превратить, сделать»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ مَفْعُولَيْنِ</span><span class="rule-table-ru">ставит два дополнения в винительный падеж</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَعَلَ اللَّهُ الْخَمْرَ حَرَامًا. جَعَلْتُ الْمَاءَ ثَلْجًا.</span><span class="rule-table-ru">Аллах сделал вино запретным. Я превратил воду в лёд.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَى ظَنَّ</span><span class="rule-table-ru">значение «счесть, полагать»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ مَفْعُولَيْنِ</span><span class="rule-table-ru">ставит два дополнения в винительный падеж</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَجَعَلْتَنِي مُدِيرًا؟</span><span class="rule-table-ru">Ты счёл меня директором?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِنْ أَفْعَالِ الشُّرُوعِ</span><span class="rule-table-ru">глагол начала действия</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَعْمَلُ عَمَلَ كَانَ</span><span class="rule-table-ru">действует как كَانَ</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَعَلَ الْمُدَرِّسُ يَشْرَحُ الدَّرْسَ.</span><span class="rule-table-ru">Преподаватель начал объяснять урок.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَى أَوْجَدَ</span><span class="rule-table-ru">значение «создать»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ يَنْصِبُ مَفْعُولًا وَاحِدًا</span><span class="rule-table-ru">полный глагол с одним дополнением</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَعَلَ اللَّهُ الْهَوَاءَ.</span><span class="rule-table-ru">Аллах создал воздух.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример значения ظَنَّ</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًا﴾</span><span class="rule-example-ru">«Они сочли ангелов, которые являются рабами Милостивого, женщинами»: جَعَلَ здесь требует два дополнения.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор جَعَلَ как глагола начала</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">الْمُدَرِّسُ: اسْمُ جَعَلَ مَرْفُوعٌ.</span><span class="rule-example-ru">الْمُدَرِّسُ — имя جَعَلَ в именительном падеже.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">جُمْلَةُ «يَشْرَحُ» فِي مَحَلِّ نَصْبٍ خَبَرُ جَعَلَ.</span><span class="rule-example-ru">Глагольное предложение с يَشْرَحُ занимает винительное место сказуемого جَعَلَ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример значения أَوْجَدَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ﴾</span><span class="rule-example-ru">«И создал мраки и свет»: جَعَلَ употреблён как полный глагол со значением создания.</span></div></div></div></div>', 'جَعَلَ может означать «превратить», «счесть», начало действия либо «создать». Первые два значения требуют два дополнения, значение начала действует как كَانَ, а значение создания требует одно дополнение.', 'لِجَعَلَ أَرْبَعَةُ مَعَانٍ: مَعْنَى صَيَّرَ وَمَعْنَى ظَنَّ، وَفِي هَذَيْنِ تَنْصِبُ مَفْعُولَيْنِ؛ وَتَأْتِي مِنْ أَفْعَالِ الشُّرُوعِ فَتَعْمَلُ عَمَلَ كَانَ؛ وَتَأْتِي بِمَعْنَى أَوْجَدَ فَتَكُونُ فِعْلًا تَامًّا يَنْصِبُ مَفْعُولًا وَاحِدًا.'),
    (6, 'فَتْحُ يَاءِ الْمُتَكَلِّمِ (фатха на يَاءِ الْمُتَكَلِّمِ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">تَكُونُ يَاءُ الْمُتَكَلِّمِ مَفْتُوحَةً إِذَا اتَّصَلَتْ بِاسْمٍ آخِرُهُ أَلِفٌ سَاكِنَةٌ، أَوْ بِاسْمٍ آخِرُهُ يَاءٌ سَاكِنَةٌ.</span><p class="rule-study-text">يَاءُ الْمُتَكَلِّمِ получает фатху после имени, которое заканчивается неподвижной алиф, а также после имени, которое заканчивается неподвижной ي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два положения и все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">آخِرُ الِاسْمِ</span><span class="rule-table-ru">окончание имени</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">формы с يَاءِ الْمُتَكَلِّمِ</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَلِفٌ سَاكِنَةٌ</span><span class="rule-table-ru">неподвижная алиф</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَصَايَ، وَفَتَايَ، وَدُنْيَايَ</span><span class="rule-table-ru">три примера с открытой يَاءُ الْمُتَكَلِّمِ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَصَايَ؛ فَتَايَ؛ دُنْيَايَ</span><span class="rule-table-ru">моя трость; мой юноша; мой земной мир</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَاءٌ سَاكِنَةٌ</span><span class="rule-table-ru">неподвижная ي</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">غَسَلْتُ عَيْنَيَّ وَيَدَيَّ.</span><span class="rule-table-ru">пример с двумя двойственными именами</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَيْنَيَّ؛ يَدَيَّ</span><span class="rule-table-ru">мои два глаза; мои две руки — «Я вымыл глаза и руки».</span></td></tr></tbody></table></div></div></div>', 'يَاءُ الْمُتَكَلِّمِ получает фатху после имени, которое заканчивается неподвижной алиф, а также после имени, которое заканчивается неподвижной ي.', 'تَكُونُ يَاءُ الْمُتَكَلِّمِ مَفْتُوحَةً إِذَا اتَّصَلَتْ بِاسْمٍ آخِرُهُ أَلِفٌ سَاكِنَةٌ، أَوْ بِاسْمٍ آخِرُهُ يَاءٌ سَاكِنَةٌ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '8'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '8'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الثَّامِنُ
بَـابُ اسْتَفْعَلَ
من أمثلته : اِسْتَخْرَجَ , اِسْتَكْبَرَ , اِسْتَعَانَ , اِسْتَغْنَى .
أحرف الزيادة : الهمزة ، والسِّين ، والتَّاء .
مصدره : اِسْتِفْعَالٌ ( كسر الثالث ، وزيادة الألف قبل الآخر ) .
نحو : اسْتَكْبَرَ : اسْتِكْبَارٌ ، اسْتَغْنَى : اسْتِغْنَاءٌ ، اسْتَغْفَرَ : اسْتِغْفَارٌ .
من معانيه :
1- الطَّلَبُ ، نحو : اسْتَغْفَرَ ، واسْتَهْدَى ، أي : طَلَبَ المغفرةَ ، والهِدايةَ .
2- الصَّيْرُورَةُ ، نحو : اسْتَحْجَرَ الطِّينُ ، أي : صَارَ حَجَراً .
3- التَّشَبُّهُ ، نحو : اسْتَرْجَلَتِ الْمَرْأَةُ ، أي : تَشَبَّهَتْ بالرَّجُلِ .
المشتقات :
اسم المفعول
| اسم الفاعل
| المصدر
