| اِسْتَخْرِجْ
| يَسْتَخْرِجُ
| اِسْتَخْرَجَ
|
| مُسْتَهْدًى
| مُسْتَهْدٍ
| اِسْتِهْدَاءٌ
| اِسْتَهْدِ
| يَسْتَهْدِي
| اِسْتَهْدَى
|
| ( لازم )
| مُسْتَعِيْذٌ
| اِسْتِعَاذَةٌ
| اِسْتَعِذْ
|     يَسْتَعِيذُ
| اِسْتَعَاذَ
|', 31, 32, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
