insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'دخولُ قَدْ على الجملةِ الْحَالِيَّةِ
إذا دخلت واو الحال على جملة فعلية فعلها ماضٍ مُثْبَتٌ دخلت معها قد ، نحو :
دخلتُ المسجدَ وقد ركعَ الإمامُ . جملة ( قد ركع الإمامُ ) في محل نصب حال ، ونحو : دخلت الفصل وقد شرح المدرِّسُ الدَّرسَ .', 32, 32, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'نَوَاصِبُ الفعلِ المضارعِ
نواصب الفعل المضارع أربعة أحرف , هي :
1- أَنْ
أَنْ : حرف نصب , ومصدر , واستقبال , نحو : أُريدُ أنْ أشربَ ، تقدير المصدر :
أريدُ الشُّرْبَ .
ونحو قوله تعالى : ﴿ وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ ﴾ والتقدير : يريدُ اللهُ التوبةَ عليكم .
لَنْ 2-
لَنْ : حرف نصب , ونفي , واستقبال , نحو : لن تذهبَ معي ، ونحو قوله تعالى :
﴿ قَالَ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا ﴾ .
3- كَيْ
كَيْ : حرف نصب , ومصدر , واستقبال ، تقترن بلام التَّعْلِيل كثيرا ، فإن لم تقترن بها فهي مُقَدَّرَةٌ .
قد تتصل بها ( لا ) النَّافية ، وتكتب هكذا ( لِكَيْلاَ ) .
الأمثلة :
جئت لكي أتعلَّمَ ، التقدير : جئتُ للتعلُّمِ .
ونحو: جِئْتُ كي أتعلَّمَ . اِجْتَهَدْتُ لكيلا أرسبَ. ومنه قوله تعالى: ﴿ كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ ﴾ .
الإعراب : جئتُ لكي أتعلَّمَ .
جئت : جاء فعل ماضٍ مبني على السكون لاتصاله بالتاء ، والتاء ضمير رفع مبني على الضم في محل رفع فاعل .
اللام : حرف جر مبني على الكسر لا محل له من الإعراب .
كي : حرف نصب ومصدر مبني على السكون لا محل له من الإعراب .
أتعلَّمَ : فعل مضارع منصوب بكي وعلامة نصبه الفتحة الظاهرة ، والمصدر المؤول
(كي أتعلَّم ) في محل جر .
4- إِذَنْ
إِذَنْ : حرف نصب ، وجواب ، وجزاء ، واستقبال .
شروط عملها :
1- أَنْ تَتَصَدَّرَ جملةَ الجوابِ .
2- أن لا يَفْصِلَ بينها وبين الفعل فاصلٌ ، إلا القسم ، أو ( لا ) النافية .
3- أن يكون زمن الفعل الاستقبال .
وتتحقق هذه الشروط في نحو : سأزورك غداً . إذن أنتظرَك .
ويجوز : إذن واللهِ أنتظرَك ( الفصل بالقسم ) ويجوز : إذن لا أخرجَ من البيت ( الفصل بـ لا النافية ) .
فإذا لم يتحقق شرط من الشروط السابقة لم تعمل النصب .
نحو : أنا إذن أنتظرُك : بالرفع ؛ لأن إذن غير متصدرة .
إذن أنا أنتظرُك : بالرفع ؛ لأن الفاصل ليس القسم ، أولا النافية .
إذن أنتظرُك الآن : بالرفع ؛ لأن زمن الفعل الحال .
الإعراب : إذنْ أنتظرَك .
إذنْ : حرف نصب مبني على السكون لا محل له من الإعراب .
أنتظرَك : فعل مضارع منصوب بإذن وعلامة نصبه الفتحة الظاهرة ، والفاعل ضمير
مستتر ، تقديره ( أنا ) .
وكاف المخاطب : ضمير نصب متصل مبني على الفتح في محل نصب مفعول به .
إذنْ وَاللهِ أنتظرَك .
إذن : حرف نصب مبني على السكون لا محل له من الإعراب .
والله : الواو للقسم حرف جر مبني على الفتح لا محل له من الإعراب .
ولفظ الجلالة ( الله ) اسم مجرور وعلامة جره الكسرة الظاهرة .
وجملة القسم لا محل لها من الإعراب ؛ لأنها جملةٌ اعْتِرَاضِيَّةٌ .
أنتظرَك : تُعْرَبُ الإعرابَ السَّابِقَ .', 32, 35, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مَعَانِي جَعَلَ
لِجَعَلَ أربعةُ معانٍ ، هي :
1- معنى صَيَّرَ ، نحو : جعل الله الخمرَ حراماً ، جعلت الماءَ ثلجاً .
2- معنى ظَنَّ ، نحو قوله تعالى : ﴿ وَجَعَلُوا الْمَلَائِكَةَ الَّذِينَ هُمْ عِبَادُ الرَّحْمَنِ إِنَاثًا ﴾ ونحو قولك : أجعلتني مديراً ؟ وهي بهذين المعنيين تنصب مفعولين .
3- من أفعال الشروع ، تعمل عمل كان ، نحو : جعل المدرِّسُ يَشْرَحُ الدَّرسَ .
فـ ( المدرِّسُ ) اسم جعل مرفوع , وجملة ( يشرح ) في محل نصب خبر جعل .
4- معنى أَوْجَدَ : وهو فعل تَامٌّ ينصب مفعولا واحدا ، نحو : جعلَ اللهُ الهواءَ .
ومنه قوله تعالى : ﴿ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ ﴾ .', 35, 35, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'فَتْحُ يَاءِ المتكلَّم
1- تكونُ ياءُ المتكلِّمِ مفتوحةً مع اسمٍ آخرُه ألفٌ ساكنةٌ ، نحو : عَصَايَ ، وفَتَايَ ، ودُنْيَايَ .
2- وتكونُ مفتوحةً كذلك مع اسم آخره ياء ساكنة ، نحو : غَسَلْتُ عَيْنَيَّ ، ويَدَيَّ .', 35, 35, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and sort_order = 6;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '8' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '8';
  if updated_count <> 6 or source_count <> 6 then
    raise exception 'Book 4 lesson 8 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
